extra_css:
/* Rift Garage surfaces: panels are scuffed workshop sheet metal with rivets in the corners, lit green from the rift on one side and
   warm from the bulb on the other; hover makes a panel crackle (green edge brightens, a faint glitch offset). Scoped to own surfaces. */
html[data-atmo="rift"] .card, html[data-atmo="rift"] .panel, html[data-atmo="rift"] .gx-card {
  background:
    radial-gradient(circle at 10px 10px, rgba(200,220,205,.35) 0 2px, transparent 3px), radial-gradient(circle at calc(100% - 10px) 10px, rgba(200,220,205,.35) 0 2px, transparent 3px),
    radial-gradient(120% 80% at 100% 0%, rgba(109,255,138,.10), transparent 55%), radial-gradient(90% 70% at 0% 0%, rgba(255,190,110,.06), transparent 60%),
    repeating-linear-gradient(100deg, rgba(255,255,255,.012) 0 2px, transparent 2px 7px), linear-gradient(180deg, rgba(26,32,28,.86), rgba(8,10,9,.92));
  backdrop-filter: blur(10px) saturate(140%); -webkit-backdrop-filter: blur(10px) saturate(140%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), inset 0 0 0 1px rgba(109,255,138,.16), 0 0 26px rgba(109,255,138,.07), 0 20px 50px rgba(0,0,0,.7);
  transition: box-shadow .25s, transform .25s cubic-bezier(.2,1.3,.4,1); }
html[data-atmo="rift"] .card:hover, html[data-atmo="rift"] .gx-card:hover {
  transform: translateY(-2px); box-shadow: inset 0 1px 0 rgba(255,255,255,.12), inset 0 0 0 1px rgba(109,255,138,.5), 0 0 34px rgba(109,255,138,.2), 2px 0 0 rgba(255,80,200,.18), -2px 0 0 rgba(109,255,138,.22), 0 24px 60px rgba(0,0,0,.75); }
html[data-atmo="rift"] h1, html[data-atmo="rift"] h2 { text-shadow: 0 0 14px rgba(109,255,138,.5), 0 0 2px rgba(220,255,225,.8); }

